/* =====================================================
   PROCEDIMIENTO: DETERMINAR GANADOR
   El jugador con m s puntos gana autom ticamente.
   En empate se usan l neas eliminadas.
   ===================================================== */

CREATE PROCEDURE DeterminarGanador
    @PartidaId INT
AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @GanadorId INT;


    SELECT TOP 1
        @GanadorId = UsuarioId

    FROM ParticipantesPartida

    WHERE PartidaId = @PartidaId

    ORDER BY
        Puntuacion DESC,
        LineasEliminadas DESC,
        UsuarioId ASC;


    UPDATE Partidas

    SET
        GanadorId = @GanadorId,
        Estado = 'Finalizada',
        FechaFin = SYSDATETIME()

    WHERE PartidaId = @PartidaId;


    SELECT
        @GanadorId AS GanadorId;

END;

/* =====================================================
   PROCEDIMIENTO: ELIMINAR COLUMNA
   La pieza especial elimina bloques de otros jugadores.
   ===================================================== */

CREATE PROCEDURE EliminarColumna
    @PartidaId INT,
    @UsuarioAtacanteId INT,
    @Columna INT
AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @TableroId INT;
    DECLARE @CantidadEliminada INT;


    SELECT
        @TableroId = TableroId

    FROM TablerosPartida

    WHERE PartidaId = @PartidaId;


    SELECT
        @CantidadEliminada = COUNT(*)

    FROM BloquesTablero

    WHERE TableroId = @TableroId
      AND Columna = @Columna
      AND UsuarioId <> @UsuarioAtacanteId
      AND Activo = 1;


    UPDATE BloquesTablero

    SET Activo = 0

    WHERE TableroId = @TableroId
      AND Columna = @Columna
      AND UsuarioId <> @UsuarioAtacanteId
      AND Activo = 1;


    INSERT INTO EliminacionesBloques
    (
        PartidaId,
        UsuarioAtacanteId,
        ColumnaAfectada,
        CantidadBloquesEliminados,
        PuntosObtenidos
    )
    VALUES
    (
        @PartidaId,
        @UsuarioAtacanteId,
        @Columna,
        @CantidadEliminada,
        @CantidadEliminada * 10
    );


    UPDATE ParticipantesPartida

    SET Puntuacion =
        Puntuacion + (@CantidadEliminada * 10)

    WHERE PartidaId = @PartidaId
      AND UsuarioId = @UsuarioAtacanteId;


    SELECT
        @CantidadEliminada AS BloquesEliminados;

END;
